 internal static class AcquiredManualReservationTests
 {
  const string Anchor="11111111-1111-4111-8111-111111111111",Campaign="22222222-1111-4111-8111-111111111111",Area="0123456789abcdef0123456789abcdef",OtherArea="fedcba9876543210fedcba9876543210";
  static int Main()
  {
   var t=new TestRunner();
   t.Run("exact acquired Auto request admits only native Auto load",()=>{var f=new Fixture();TestRunner.Equal(0,f.Request.Validate().Count,string.Join(" | ",f.Request.Validate()));TestRunner.Equal("Auto",f.Request.ExpectedNativeLoadType,"Native category changed.");});
   foreach(var mutation in new[]{"missing","foreign-family","wrong-case","write2","load0","same-run","actor-alias","bad-id","Working","other-Auto","old-permission","route","alternate","source-hash","wrong-schema"})t.Run("closed protocol refuses "+mutation,()=>{var f=new Fixture();var r=f.Request;switch(mutation){case "missing":r.AcquiredManual=null;break;case "foreign-family":r.Scenario="fixture-intake";break;case "wrong-case":r.AcquiredManual.Case="arrange";break;case "write2":r.AcquiredManual.ExpectedNativeWriteCount=2;break;case "load0":r.AcquiredManual.ExpectedNativeLoadCount=0;break;case "same-run":r.AcquiredManual.SourceRunId=r.RunId;break;case "actor-alias":r.AcquiredManual.PetId=r.AcquiredManual.ActorId;break;case "bad-id":r.AcquiredManual.ActorId="actor";break;case "Working":r.PersistenceLoad.GameId=Anchor;break;case "other-Auto":r.PersistenceLoad.FileName="Auto_2.zks";break;case "old-permission":r.ManualDerived=new Chunk7ManualDerivedSelection();break;case "route":r.PersistenceAreaTarget=new RuntimeAreaTransitionTarget();break;case "alternate":r.PersistenceAlternate=r.PersistenceLoad;break;case "source-hash":r.PersistenceLoad.Sha256=new string('e',64);break;case "wrong-schema":r.SchemaVersion=1;break;}TestRunner.True(r.Validate().Count>0,"Foreign declaration admitted.");});
   t.Run("early write and load refuse without spending authority",()=>{var f=new Fixture();var a=f.Scope();TestRunner.True(a.MatchesAcquiredManualPlan(f.Request.PersistenceLoad,false,true),"Initial immutable shape missing.");TestRunner.True(!a.MatchesAcquiredManualPlan(f.Request.PersistenceLoad,true,true),"Reservation invented.");TestRunner.True(a.ValidateArchiveIdentity(f.Load,f.Root)==null,"Read-only descriptor identity is unavailable.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Unreserved native load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(7),f.Root)!=null,"Unreserved native write admitted.");Unspent(a);});
   t.Run("native observed number is used without fixed slot",()=>{var f=new Fixture();var a=f.Scope();a.ReserveAcquiredManualOutput(f.Request,f.Game,f.Manager,f.Descriptor,f.Load,7);TestRunner.Equal(7,a.AcquiredManualNumber,"Observed number replaced.");TestRunner.Equal(1,a.AcquiredManualInitialEntries,"Initial native entry count changed.");TestRunner.Equal(0,a.AcquiredManualInitialWritable,"Initial authority had a writable target.");TestRunner.Equal(2,a.AcquiredManualReservedEntries,"Reserved entry count changed.");TestRunner.Equal(1,a.AcquiredManualReservedWritable,"Reserved writable count changed.");TestRunner.Equal("Manual_7_KMC_C7_ACQUIRED_FIELD.zks",a.AcquiredManualOutputLeaf,"Observed leaf replaced.");TestRunner.True(object.ReferenceEquals(f.Descriptor,a.AcquiredManualSourceDescriptor),"Native descriptor custody lost.");TestRunner.True(a.MatchesAcquiredManualPlan(f.Request.PersistenceLoad,true,true),"Two-entry plan missing.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Reservation spent a load.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Reservation spent a write.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"One load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null,"Second load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(7),f.Root)==null,"Exact fresh Manual refused.");using(var lease=a.BeginWrite(f.Write(7),f.Root)){BootstrapVirtualFile.OutputExists=true;lease.Complete();}TestRunner.True(a.MatchesAcquiredManualPlan(f.Request.PersistenceLoad,true,false),"Settled reservation shape lost.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(7),f.Root)!=null,"Second write admitted.");TestRunner.True(a.ValidateArchiveIdentity(f.Load,f.Root)==null,"Immutable input lost.");BootstrapVirtualFile.OutputExists=false;});
   foreach(var mutation in new[]{"request-object","game","manager","descriptor-null","mutated-request","mutated-source","wrong-descriptor-campaign","wrong-descriptor-area","wrong-descriptor-type","wrong-descriptor-path","number-zero","number-negative","changed-inventory","source-bytes","output-present"})t.Run("atomic reservation refuses "+mutation,()=>{var f=new Fixture();var a=f.Scope();var r=f.Request;var g=f.Game;var m=f.Manager;var d=f.Descriptor;var target=f.Load;var n=9;switch(mutation){case "request-object":r=new Fixture().Request;break;case "game":g=new object();break;case "manager":m=new object();break;case "descriptor-null":d=null;break;case "mutated-request":r.TransactionToken=new string('9',64);break;case "mutated-source":r.PersistenceLoad.Length++;break;case "wrong-descriptor-campaign":target.GameId=Anchor;break;case "wrong-descriptor-area":target.Area=OtherArea;break;case "wrong-descriptor-type":target.SaveType="Manual";break;case "wrong-descriptor-path":target.FullPath=@"C:\foreign\Auto_1.zks";break;case "number-zero":n=0;break;case "number-negative":n=-1;break;case "changed-inventory":BootstrapVirtualDirectory.ForeignEntry=true;break;case "source-bytes":BootstrapVirtualStorage.SourceChanged=true;break;case "output-present":BootstrapVirtualFile.OutputExists=true;break;}bool refused=false;try{a.ReserveAcquiredManualOutput(r,g,m,d,target,n);}catch(InvalidOperationException){refused=true;}catch(System.IO.IOException){refused=true;}finally{Reset();}TestRunner.True(refused,"Foreign/stale reservation accepted.");Unspent(a);TestRunner.True(a.AcquiredManualOutputLeaf==null&&a.AcquiredManualSourceDescriptor==null,"Failed reservation retained a write leaf or descriptor.");});
   foreach(var number in new[]{7,8})t.Run("repeated reservation refuses without changing exact first leaf "+number,()=>{var f=new Fixture();var a=f.Scope();a.ReserveAcquiredManualOutput(f.Request,f.Game,f.Manager,f.Descriptor,f.Load,7);bool refused=false;try{a.ReserveAcquiredManualOutput(f.Request,f.Game,f.Manager,new object(),f.Load,number);}catch(InvalidOperationException){refused=true;}TestRunner.True(refused,"Duplicate reservation admitted.");TestRunner.Equal(7,a.AcquiredManualNumber,"Existing reservation mutated.");TestRunner.True(object.ReferenceEquals(f.Descriptor,a.AcquiredManualSourceDescriptor),"Existing descriptor replaced.");TestRunner.Equal(1,a.AcquiredManualReservationCount,"Reservation count changed.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Refusal spent native write.");});
   t.Run("failed enumeration can retry only clean same context",()=>{var f=new Fixture();var a=f.Scope();BootstrapVirtualDirectory.ForeignEntry=true;try{a.ReserveAcquiredManualOutput(f.Request,f.Game,f.Manager,f.Descriptor,f.Load,4);}catch(InvalidOperationException){}Reset();a.ReserveAcquiredManualOutput(f.Request,f.Game,f.Manager,f.Descriptor,f.Load,4);TestRunner.Equal(4,a.AcquiredManualNumber,"Clean retry did not preserve native observed destination.");});
   t.Run("ordinary fixed authority cannot acquire new reservation capability",()=>{var f=new Fixture();var a=f.Scope(false);bool refused=false;try{a.ReserveAcquiredManualOutput(f.Request,f.Game,f.Manager,f.Descriptor,f.Load,1);}catch(InvalidOperationException){refused=true;}TestRunner.True(refused,"Historical authority gained mutable output capability.");TestRunner.True(a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Historical read-only admission changed.");});
   foreach(var kind in new[]{"writable-input","extra-leaf","no-load-cap","no-write-cap","bootstrap","transition","foreign-input","partial-context"})t.Run("constructor refuses widened reservation "+kind,()=>{var f=new Fixture();var entries=f.Entries();int? loads=1,writes=1;object game=f.Game;string from=null,to=null;switch(kind){case "writable-input":entries[0].Writable=true;break;case "extra-leaf":entries=entries.Concat(new[]{new PersistenceSaveEntry{FileName="Manual_9_other.zks",InternalName="other",SaveType="Manual",Area=Area,Writable=true}}).ToArray();break;case "no-load-cap":loads=null;break;case "no-write-cap":writes=null;break;case "bootstrap":entries[0].Campaign="B";break;case "transition":from=Area;to=OtherArea;break;case "foreign-input":entries[0].ForeignGameId=Anchor;entries[0].ForeignGameName="other";break;case "partial-context":game=null;break;}bool refused=false;try{new PersistenceSaveAuthorization(Fixture.RunRoot,Campaign,"Native",new string('a',64),entries,from,to,writes,loads,f.Request,game,f.Manager);}catch(ArgumentException){refused=true;}TestRunner.True(refused,"Wide reservation capability admitted.");});
   foreach(var mutation in new[]{"token","actor","scenario"}) foreach(var boundary in new[]{"validate-load","authorize-load","archive-identity","new-request","readable","authorize-write","storage"}) t.Run("reserved request mutation refuses "+mutation+" at "+boundary,()=>{var f=new Fixture();var a=f.Scope();a.ReserveAcquiredManualOutput(f.Request,f.Game,f.Manager,f.Descriptor,f.Load,7);var writing=boundary=="authorize-write"||boundary=="storage";if(writing){TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Setup load refused.");if(boundary=="storage")TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(7),f.Root)==null,"Setup write refused.");}var loads=a.AdmittedNativeLoadRequests;var writes=a.AdmittedNativeWriteRequests;switch(mutation){case "token":f.Request.TransactionToken=new string('9',64);break;case "actor":f.Request.AcquiredManual.ActorId="66666666-1111-4111-8111-111111111111";break;case "scenario":f.Request.Scenario="fixture-intake";break;}TestRunner.True(!a.MatchesAcquiredManualPlan(f.Request.PersistenceLoad,true,false),"Mutated plan predicate remained true.");bool refused=false;try{switch(boundary){case "validate-load":refused=a.Validate(RuntimeSaveOperation.Load,f.Load,f.Root)!=null;break;case "authorize-load":refused=a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)!=null;break;case "archive-identity":refused=a.ValidateArchiveIdentity(f.Load,f.Root)!=null;break;case "new-request":a.ProjectNewRequest(f.Write(7),f.Root);break;case "readable":a.AssertReadableArchive(f.Load.FullPath);break;case "authorize-write":refused=a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(7),f.Root)!=null;break;case "storage":using(a.BeginWrite(f.Write(7),f.Root)){}break;}}catch(InvalidOperationException){refused=true;}TestRunner.True(refused,"Mutated captured request crossed the later native boundary.");TestRunner.Equal(loads,a.AdmittedNativeLoadRequests,"Refusal spent load.");TestRunner.Equal(writes,a.AdmittedNativeWriteRequests,"Refusal spent write.");TestRunner.Equal(1,a.AcquiredManualReservationCount,"Reservation changed.");TestRunner.Equal(7,a.AcquiredManualNumber,"Reserved number changed.");TestRunner.True(object.ReferenceEquals(f.Descriptor,a.AcquiredManualSourceDescriptor),"Descriptor custody changed.");});
   foreach(var boundary in new[]{"validate","authorize","storage"})t.Run("reserved fresh Manual refuses before cold load at "+boundary,()=>{var f=new Fixture();var a=f.Scope();a.ReserveAcquiredManualOutput(f.Request,f.Game,f.Manager,f.Descriptor,f.Load,7);bool refused=false;try{if(boundary=="validate")refused=a.Validate(RuntimeSaveOperation.Write,f.Write(7),f.Root)!=null;else if(boundary=="authorize")refused=a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Write(7),f.Root)!=null;else using(a.BeginWrite(f.Write(7),f.Root)){} }catch(InvalidOperationException){refused=true;}TestRunner.True(refused,"Write crossed reserved-before-load boundary.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Early write spent load.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Early write spent write.");TestRunner.Equal(1,a.AcquiredManualReservationCount,"Early write changed reservation.");});
   t.Run("storage needs exact native write admission after load",()=>{var f=new Fixture();var a=f.Scope();a.ReserveAcquiredManualOutput(f.Request,f.Game,f.Manager,f.Descriptor,f.Load,7);TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Load,f.Root)==null,"Setup load refused.");bool refused=false;try{using(a.BeginWrite(f.Write(7),f.Root)){} }catch(InvalidOperationException){refused=true;}TestRunner.True(refused,"Storage opened without native request admission.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Storage refusal spent write.");});
   return t.Complete();
  }
  static void Reset(){BootstrapVirtualDirectory.ForeignEntry=false;BootstrapVirtualFile.OutputExists=false;BootstrapVirtualStorage.SourceChanged=false;}
  static void Unspent(PersistenceSaveAuthorization a){TestRunner.Equal(0,a.AcquiredManualReservationCount,"Refusal changed reservation.");TestRunner.Equal(0,a.AcquiredManualReservedEntries,"Refusal populated reserved entry receipt.");TestRunner.Equal(0,a.AcquiredManualReservedWritable,"Refusal populated writable receipt.");TestRunner.Equal(0,a.AdmittedNativeLoadRequests,"Refusal spent load.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Refusal spent write.");}
  static RuntimeSaveDescriptor Descriptor(string n,string f,string h)=>new RuntimeSaveDescriptor{InternalName=n,FileName=f,Sha256=h,Length=10,LastWriteTimeUtcTicks=638907120000000000L,GameId=Anchor,GameName="Anchor",Area=Area};
  sealed class Fixture
  {
   internal const string RunRoot=@"C:\KmcBootstrapVirtual\run";internal readonly string Root=RunRoot+@"\Saved Games";
   internal readonly object Game=new object(),Manager=new object(),Descriptor=new object();
   internal readonly RuntimeRequest Request=new RuntimeRequest{SchemaVersion=2,RunId="acquired-test",Scenario=Chunk7AcquiredManualSelection.Scenario,AcquiredManual=new Chunk7AcquiredManualSelection{Case=Chunk7AcquiredManualSelection.CaseName,SourceRunId="completed-acquisition",SourceArtifactSha256=new string('c',64),SourceArchiveSha256=new string('d',64),ActorId="44444444-1111-4111-8111-111111111111",PetId="55555555-1111-4111-8111-111111111111",BaseGameOnly=true,ExpectedNativeLoadCount=1,ExpectedNativeWriteCount=1},PersistenceLoad=new RuntimeSaveDescriptor{FileName="Auto_1.zks",InternalName="Autosave",Sha256=new string('d',64),Length=10,LastWriteTimeUtcTicks=638907120000000000L,GameId=Campaign,GameName="Native",Area=Area},Branch="codex/mounted-combat-chunk7-foundation",Commit=new string('1',40),ProductVersion=BuildIdentity.ProductVersion,DllSha256=new string('2',64),DllMvid=Anchor,TransactionToken=new string('3',64),EvidenceRoot=@"C:\KmcBootstrapVirtual\evidence",Fixture=new RuntimeFixtureIdentity{Baseline=AcquiredManualReservationTests.Descriptor("KMC_AUTOMATION_BASELINE","Manual_298_KMC_AUTOMATION_BASELINE.zks",new string('a',64)),Working=AcquiredManualReservationTests.Descriptor("KMC_AUTOMATION_WORKING","Manual_299_KMC_AUTOMATION_WORKING.zks",new string('b',64)),WriteAuthorization=new RuntimeSaveWriteAuthorization{Mode="working-only",AllowedInternalName="KMC_AUTOMATION_WORKING",AllowedFileName="Manual_299_KMC_AUTOMATION_WORKING.zks",BaselineImmutable=true}},QualificationSuite=new RuntimeQualificationSuiteIdentity{SuiteId="bootstrap-suite",SnapshotSha256=new string('4',64)}};
   internal RuntimeSaveTarget Load=>new RuntimeSaveTarget{InternalName="Autosave",FileName="Auto_1.zks",FullPath=Root+@"\Auto_1.zks",SaveType="Auto",GameId=Campaign,GameName="Native",Area=Area};
   internal RuntimeSaveTarget Write(int n)=>new RuntimeSaveTarget{InternalName=Chunk7AcquiredManualSelection.OutputName,FileName=Chunk7AcquiredManualSelection.NativeOutputLeaf(n),FullPath=Root+"\\"+Chunk7AcquiredManualSelection.NativeOutputLeaf(n),SaveType="Manual",GameId=Campaign,GameName="Native",Area=Area};
