   internal PersistenceSaveAuthorization Scope(bool selected=true){Reset();return new PersistenceSaveAuthorization(RunRoot,Campaign,"Native",new string('a',64),Entries(),null,null,1,1,selected?Request:null,selected?Game:null,selected?Manager:null);}
  }
 }
 internal static class BootstrapVirtualDirectory {internal static bool ForeignEntry;internal static IEnumerable<string> EnumerateFileSystemEntries(string path)=>ForeignEntry?new[]{path+@"\Auto_1.zks",path+@"\foreign.zks"}:new[]{path+@"\Auto_1.zks"};internal static bool Exists(string path)=>!path.EndsWith(".zks",StringComparison.Ordinal);}
 internal static class BootstrapVirtualFile {internal static bool OutputExists;internal static bool Exists(string path)=>path.EndsWith("Auto_1.zks",StringComparison.Ordinal)||(OutputExists&&path.Contains("KMC_C7_ACQUIRED_FIELD"));internal static void Delete(string path){throw new InvalidOperationException("Unexpected filesystem mutation.");}}
 internal static class BootstrapVirtualStorage {internal static bool SourceChanged;internal static void RequireDirectory(string path){if(string.IsNullOrEmpty(path))throw new InvalidOperationException();}internal static string Hash(string path)=>new string(path.EndsWith("Auto_1.zks",StringComparison.Ordinal)?(SourceChanged?'e':'d'):'f',64);}
